glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  #if USE_TEXTURE
  v_uv0 = a_uv0;
  #endif
  v_color = a_color;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif
uniform CenterColorParams {
  vec4 centerColorParam;
  vec4 centerGradientParam;
  vec4 centerParams1;
  vec4 centerParams2;
  vec4 centerParams3;
};
vec3 rgb2hsv(vec3 c) {
  vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
  vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
  vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
  float d = q.x - min(q.w, q.y);
  float e = 1.0e-10;
  return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}
vec3 hsv2rgb(vec3 c) {
  vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
  vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
  return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}
vec3 adjustHue(vec3 color, float hue) {
  vec3 hsv = rgb2hsv(color);
  hsv.x = fract(hsv.x + hue / 360.0);
  return hsv2rgb(hsv);
}
vec3 adjustSaturation(vec3 color, float saturation) {
  vec3 hsv = rgb2hsv(color);
  hsv.y *= saturation;
  return hsv2rgb(hsv);
}
vec3 adjustContrast(vec3 color, float contrast) {
  return clamp((color - 0.5) * contrast + 0.5, 0.0, 1.0);
}
vec3 adjustBrightness(vec3 color, float brightness) {
  return color * brightness;
}
vec3 applyBlendMode(vec3 base, vec3 blend, float mode) {
  if (mode < 0.5) {
    return mix(base, blend, 1.0);
  } else if (mode < 1.5) {
    return base * blend;
  } else if (mode < 2.5) {
    vec3 overlay1 = 2.0 * base * blend;
    vec3 overlay2 = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
    vec3 result;
    result.r = base.r < 0.5 ? overlay1.r : overlay2.r;
    result.g = base.g < 0.5 ? overlay1.g : overlay2.g;
    result.b = base.b < 0.5 ? overlay1.b : overlay2.b;
    return result;
  } else if (mode < 3.5) {
    return 1.0 - (1.0 - base) * (1.0 - blend);
  } else if (mode < 4.5) {
    vec3 soft1 = base - (1.0 - 2.0 * blend) * base * (1.0 - base);
    vec3 soft2 = base + (2.0 * blend - 1.0) * (sqrt(base) - base);
    vec3 result;
    result.r = blend.r < 0.5 ? soft1.r : soft2.r;
    result.g = blend.g < 0.5 ? soft1.g : soft2.g;
    result.b = blend.b < 0.5 ? soft1.b : soft2.b;
    return result;
  } else if (mode < 5.5) {
    vec3 hard1 = 2.0 * base * blend;
    vec3 hard2 = 1.0 - 2.0 * (1.0 - base) * (1.0 - blend);
    vec3 result;
    result.r = blend.r < 0.5 ? hard1.r : hard2.r;
    result.g = blend.g < 0.5 ? hard1.g : hard2.g;
    result.b = blend.b < 0.5 ? hard1.b : hard2.b;
    return result;
  } else if (mode < 6.5) {
    return min(base, blend);
  } else if (mode < 7.5) {
    return max(base, blend);
  } else {
    return clamp(base + blend - 1.0, 0.0, 1.0);
  }
}
vec4 applyCenterColorAdjustments(vec4 originalColor, vec2 uv) {
  vec3 color = originalColor.rgb;
  if (centerParams3.y > 0.5) {
    color = applyBlendMode(color, centerColorParam.rgb, centerParams2.y);
    color = adjustBrightness(color, centerParams1.x);
    color = adjustContrast(color, centerParams1.y);
    color = adjustSaturation(color, centerParams1.z);
    color = adjustHue(color, centerParams1.w);
  } else {
    vec3 targetColor = centerColorParam.rgb;
    targetColor = adjustBrightness(targetColor, centerParams1.x);
    targetColor = adjustContrast(targetColor, centerParams1.y);
    targetColor = adjustSaturation(targetColor, centerParams1.z);
    targetColor = adjustHue(targetColor, centerParams1.w);
    color = targetColor;
  }
  if (centerParams3.x > 0.5 && centerParams2.x > 0.0) {
    float gradientFactor = 0.0;
    if (centerParams2.w < 0.5) {
      float angleRad = radians(centerParams2.z);
      vec2 gradientDir = vec2(cos(angleRad), sin(angleRad));
      vec2 centeredUV = uv - vec2(0.5);
      float projection = dot(centeredUV, gradientDir);
      gradientFactor = (projection + 0.707) / 1.414;
    } else {
      gradientFactor = length(uv - vec2(0.5)) * 2.0;
    }
    gradientFactor = clamp(gradientFactor, 0.0, 1.0);
    float strength = centerParams2.x;
    float mixAmount = 0.0;
    if (strength <= 0.5) {
      mixAmount = gradientFactor * (strength * 2.0);
    } else {
      float enhanceFactor = (strength - 0.5) * 2.0;
      mixAmount = gradientFactor + (gradientFactor * enhanceFactor * 0.5);
    }
    mixAmount = clamp(mixAmount, 0.0, 1.0);
    color = mix(color, centerGradientParam.rgb, mixAmount);
  }
  return vec4(color, originalColor.a);
}
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  #if USE_TEXTURE
  o = texture2D(texture, v_uv0);
  #endif
  o *= v_color;
  ALPHA_TEST(o);
  o = applyCenterColorAdjustments(o, v_uv0);
  gl_FragColor = o;
}

